type Phase = "idle" | "running" | "done"
type MockIncident = (typeof INCIDENTS)[number]
type DecisionStatus =
  "evaluating" | "on hold" | "needs human review" | "approved"

type RunStage = {
  label: "Incident" | "Candidates" | "Outreach Tasks" | "Claims" | "Decision"
  afterId: string | null
}

const RUN_STAGES: RunStage[] = [
  { label: "Incident", afterId: null },
  { label: "Candidates", afterId: "suppliers" },
  { label: "Outreach Tasks", afterId: "outreach" },
  { label: "Claims", afterId: "claims" },
  { label: "Decision", afterId: "strategy" },
]

const hoursToLineStop = Number(INCIDENT.lineStopDays) * 24
const standingStill = `${INCIDENT.lineStopCostPerHour.replace(/\.00$/, "")} / h`

function groupThousands(qty: string): string {
  return Number(qty).toLocaleString("en-US").replaceAll(",", "\u00a0")
}

function isStepVisible(stepId: string, visible: number): boolean {
  const index = SCRIPT.findIndex((step) => step.id === stepId)
  return index >= 0 && visible > index
}

export function CockpitChat() {
  const [started, setStarted] = useState(false)
  const [visible, setVisible] = useState(0)
  const [approved, setApproved] = useState(false)
  const [selectedIncident, setSelectedIncident] = useState<MockIncident | null>(
    null
  )
  const [submittedPrompt, setSubmittedPrompt] = useState("")
  const phase: Phase = !started
    ? "idle"
    : visible >= SCRIPT.length
      ? "done"
      : "running"

  useEffect(() => {
    if (!started) {
      return
    }
    if (visible >= SCRIPT.length) {
      return
    }
    const id = window.setInterval(() => {
      setVisible((count) => Math.min(count + 1, SCRIPT.length))
    }, TICK_MS)
    return () => window.clearInterval(id)
  }, [started, visible])

  const currentStep =
    phase === "idle"
      ? "Awaiting launch"
      : visible === 0
        ? "Launching"
        : SCRIPT[Math.min(visible, SCRIPT.length) - 1].kind === "decision"
          ? "Decision ready"
          : SCRIPT[Math.min(visible, SCRIPT.length) - 1].stepName
  const checksPassed = isStepVisible("tests", visible)
  const decisionExists = isStepVisible("strategy", visible)
  const decisionStatus: DecisionStatus = approved
    ? "approved"
    : phase === "done" && !checksPassed
      ? "on hold"
      : checksPassed
        ? "needs human review"
        : "evaluating"

  function launch(prompt: string) {
    if (!selectedIncident?.href) {
      return
    }
    const skipTicks = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches
    setSubmittedPrompt(
      prompt.trim() || `Resolve Incident ${selectedIncident.caseId}.`
    )
    setStarted(true)
    setVisible(skipTicks ? SCRIPT.length : 0)
    setApproved(false)
  }

  function replay() {
    const skipTicks = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches
    setVisible(skipTicks ? SCRIPT.length : 0)
    setApproved(false)
  }

  function reset() {
    setStarted(false)
    setVisible(0)
    setApproved(false)
    setSelectedIncident(null)
    setSubmittedPrompt("")
  }

  return (
    <CockpitShell>
      {phase === "idle" ? (
        <StartSession
          selectedIncident={selectedIncident}
          onSelectIncident={setSelectedIncident}
          onLaunch={launch}
        />
      ) : (
        <div className="grid min-h-0 flex-1 grid-cols-1 xl:grid-cols-[minmax(0,1fr)_26rem]">
          <div className="flex min-h-0 min-w-0 flex-col">
            <IncidentHeader />
            <RunControls phase={phase} onReplay={replay} onReset={reset} />
            <Conversation className="min-h-0">
              <ConversationContent className="gap-4">
                <Message from="user">
                  <MessageContent>
                    <MessageResponse>{submittedPrompt}</MessageResponse>
                  </MessageContent>
                </Message>

                <SourcingRunRail
                  visible={visible}
                  started={started}
                  approved={approved}
                />

                {SCRIPT.slice(0, visible).map((step, index) => (
                  <AssistantTurn
                    key={step.id}
                    step={step}
                    latest={index === visible - 1 && phase === "running"}
                  />
                ))}

                {phase === "running" ? (
                  <div className="flex items-center gap-2 text-sm text-muted-foreground">
                    <DotLoader />
                    <span>{currentStep}</span>
                  </div>
                ) : null}
              </ConversationContent>
              <ConversationScrollButton />
            </Conversation>
            {decisionExists ? (
              <DecisionBar
                checksPassed={checksPassed}
                status={decisionStatus}
                onApprove={() => setApproved(true)}
              />
            ) : null}
          </div>
          <div className="hidden min-h-0 min-w-0 xl:block">
            <CandidatePanel visible={visible} />
          </div>
        </div>
      )}
      <Suspense fallback={null}>
        <CallDetailDialog />
      </Suspense>
    </CockpitShell>
  )
}

function StartSession({
  selectedIncident,
  onSelectIncident,
  onLaunch,
}: {
  selectedIncident: MockIncident | null
  onSelectIncident: (incident: MockIncident | null) => void
  onLaunch: (prompt: string) => void
}) {
  return (
    <div className="flex min-h-0 flex-1 flex-col bg-background">
      <header className="flex h-11 shrink-0 items-center gap-2 border-b border-border/70 px-3">
        <SidebarTrigger />
        <h1 className="ml-auto text-sm font-medium">Stockout</h1>
      </header>
      <main className="flex min-h-0 flex-1 items-center justify-center px-4 pb-[12vh]">
        <Composer
          selectedIncident={selectedIncident}
    )
  }

  if (step.kind === "decision") {
    return (
      <p className="text-sm text-muted-foreground">
        Winning Strategy: split 20% SKF air + 80% FAG sea. Required checks
        passed.
      </p>
    )
  }

  return null
}

function Composer({
  selectedIncident,
  onSelectIncident,
  onLaunch,
}: {
  selectedIncident: MockIncident | null
  onSelectIncident: (incident: MockIncident | null) => void
  onLaunch: (prompt: string) => void
}) {
  const [incidentDialogOpen, setIncidentDialogOpen] = useState(false)
  const textareaRef = useRef<HTMLTextAreaElement>(null)

  function selectIncident(incident: MockIncident) {
    if (!incident.href) {
      return
    }
    onSelectIncident(incident)
    setIncidentDialogOpen(false)
    window.requestAnimationFrame(() => textareaRef.current?.focus())
  }

  return (
    <>
      <PromptInput
        className="w-full max-w-2xl"
        onSubmit={({ text }) => {
          if (selectedIncident?.href) {
            onLaunch(text || USER_PROMPT)
          }
        }}
      >
        {selectedIncident ? (
          <PromptInputHeader>
            <Attachment size="xs" className="min-w-0">
              <AttachmentMedia>
                <TriangleAlertIcon aria-hidden="true" />
              </AttachmentMedia>
              <AttachmentContent>
                <AttachmentTitle>
                  {selectedIncident.caseId} · {INCIDENT.partId}
                </AttachmentTitle>
              </AttachmentContent>
              <AttachmentActions>
                <AttachmentAction
                  aria-label={`Remove ${selectedIncident.caseId}`}
                  onClick={() => onSelectIncident(null)}
                >
                  <XIcon aria-hidden="true" />
                </AttachmentAction>
              </AttachmentActions>
            </Attachment>
          </PromptInputHeader>
        ) : null}
        <PromptInputBody>
          <PromptInputTextarea
            ref={textareaRef}
            aria-label="Sourcing instruction"
            placeholder={
              selectedIncident
                ? "Add an instruction (optional)"
                : "Select an Incident, then add an instruction"
            }
          />
        </PromptInputBody>
        <PromptInputFooter>
          <PromptInputTools>
            <DropdownMenu>
              <DropdownMenuTrigger
                render={<PromptInputButton aria-label="Add context" />}
              >
                <PlusIcon aria-hidden="true" />
              </DropdownMenuTrigger>
              <DropdownMenuContent className="w-44">
                <DropdownMenuGroup>
                  <DropdownMenuItem onClick={() => setIncidentDialogOpen(true)}>
                    <TriangleAlertIcon aria-hidden="true" />
                    Select Incident
                  </DropdownMenuItem>
                  <DropdownMenuItem disabled>
                    <FileIcon aria-hidden="true" />
                    Select file
                  </DropdownMenuItem>
                </DropdownMenuGroup>
              </DropdownMenuContent>
            </DropdownMenu>
          </PromptInputTools>
          <PromptInputSubmit
            aria-disabled={!selectedIncident?.href}
            className="aria-disabled:pointer-events-none aria-disabled:opacity-50"
            onClick={(event) => {
              if (!selectedIncident?.href) {
                event.preventDefault()
              }
            }}
            status="ready"
          >
            <ArrowUpIcon aria-hidden="true" />
          </PromptInputSubmit>
        </PromptInputFooter>
      </PromptInput>

      <Dialog open={incidentDialogOpen} onOpenChange={setIncidentDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Select Incident</DialogTitle>
            <DialogDescription>
              Choose the Incident that Stockout should resolve.
            </DialogDescription>
          </DialogHeader>
          <ul className="flex flex-col gap-1">
            {INCIDENTS.map((incident) => {
              const available = Boolean(incident.href)

              return (
                <li key={incident.caseId}>
                  <Button
                    type="button"
                    variant="ghost"
                    className="h-auto w-full justify-start py-2 text-left whitespace-normal"
                    disabled={!available}
                    onClick={() => selectIncident(incident)}
                  >
                    <TriangleAlertIcon data-icon="inline-start" />
                    <span className="min-w-0 flex-1">
                      <span className="flex items-center gap-2">
                        <span className="font-mono text-xs">
                          {incident.caseId}
                        </span>
                        <span className="text-xs text-muted-foreground">
                          {incident.plant}
                        </span>
                      </span>
                      <span className="block truncate text-sm font-normal">
                        {incident.partLabel}
                      </span>
                    </span>
                    <Badge variant={available ? "secondary" : "outline"}>
                      {available ? "scripted" : "unavailable"}
                    </Badge>
                  </Button>
                </li>
              )
            })}
          </ul>
        </DialogContent>
      </Dialog>
    </>
  )
}

function RunControls({
  phase,
  onReplay,
  onReset,
}: {
  phase: Exclude<Phase, "idle">
  onReplay: () => void
  onReset: () => void
}) {
  const running = phase === "running"

  return (
    <div className="flex min-h-11 shrink-0 items-center justify-between gap-3 border-b border-border/70 bg-background px-4 py-2">
      <span className="text-xs text-muted-foreground">
        Rehearsal · deterministic fixture
      </span>
      <div className="flex items-center gap-1">
        <Button type="button" size="sm" variant="ghost" onClick={onReset}>
          <RotateCcwIcon data-icon="inline-start" />
          Reset
